import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o,ag as r}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse(`{"title":"T3 Code learning map","description":"T3 Code is the open-source 'control plane for coding agents' from T3 Tools, Inc. It ships no model of its own; it drives the coding agents already installed on your computer, such as Claude Code and Codex, and lets you continue from your phone after you walk away. This page gives the product family table, how to choose, and how to read the three pages in this directory.","frontmatter":{"title":"T3 Code learning map","description":"T3 Code is the open-source 'control plane for coding agents' from T3 Tools, Inc. It ships no model of its own; it drives the coding agents already installed on your computer, such as Claude Code and Codex, and lets you continue from your phone after you walk away. This page gives the product family table, how to choose, and how to read the three pages in this directory.","domain":"product","tags":["coding-agent","agent-workspace","remote-access"],"role":"map"},"headers":[],"relativePath":"products/t3code/index.md","filePath":"products/t3code/index.md","lastUpdated":1795792629000}`),d={name:"products/t3code/index.md"};function n(i,t,s,c,h,l){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="t3-code-learning-map" tabindex="-1">T3 Code learning map <a class="header-anchor" href="#t3-code-learning-map" aria-label="Permalink to &quot;T3 Code learning map&quot;">​</a></h1><blockquote><p><strong>The short version:</strong> T3 Code is an open-source local app, officially positioned as <strong>The open-source control plane for coding agents</strong>. It provides no model and replaces none of your subscriptions; it drives the coding agents already installed on your computer, puts them in one interface with one approval flow, and lets you continue from your phone after you leave the computer.</p><p>This set of pages answers four things: what it is, how to install it and get it running, how to use it day to day, and how it works inside.</p></blockquote><h2 id="basic-facts" tabindex="-1">Basic facts <a class="header-anchor" href="#basic-facts" aria-label="Permalink to &quot;Basic facts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Official name</td><td>T3 Code</td></tr><tr><td>Company</td><td>T3 Tools, Inc. (as written in the site footer, the README and the App Store developer field)</td></tr><tr><td>GitHub organization and repository</td><td><code>pingdotgg</code>; repository <a href="https://github.com/pingdotgg/t3code" target="_blank" rel="noreferrer"><code>pingdotgg/t3code</code></a></td></tr><tr><td>License</td><td>Source code under MIT. The name, logo and brand are not covered by MIT</td></tr><tr><td>Website and download</td><td><a href="https://t3.codes" target="_blank" rel="noreferrer">t3.codes</a>, <a href="https://t3.codes/download" target="_blank" rel="noreferrer">t3.codes/download</a></td></tr><tr><td>Command-line package name</td><td><code>t3</code>, for example <code>npx t3@latest</code>; packages inside the repository use the <code>@t3tools</code> scope</td></tr><tr><td>Earliest visible release record</td><td><code>v0.0.0-alpha.3</code>, released 2026-03-02 (<a href="https://github.com/pingdotgg/t3code/releases/tag/v0.0.0-alpha.3" target="_blank" rel="noreferrer">GitHub Releases</a>, as of 2026-11-24)</td></tr><tr><td>Where the docs live</td><td>In the GitHub repository: <code>docs/user/</code> covers usage, <code>docs/internals/</code> covers internal design</td></tr></tbody></table><p>When this page was checked, the t3.codes footer offered only these entries: GitHub, Discord, Download, iOS app, Android app, Terms, Privacy and Security. No separate documentation site was found.</p><h2 id="audience-prerequisites-non-goals" tabindex="-1">Audience / prerequisites / non-goals <a class="header-anchor" href="#audience-prerequisites-non-goals" aria-label="Permalink to &quot;Audience / prerequisites / non-goals&quot;">​</a></h2><ul><li><strong>Who</strong>: frontend or AI application developers who already have two or more coding agents, especially anyone who has not used an &quot;agent workspace&quot; product before.</li><li><strong>Prerequisites</strong>: a computer you control (macOS, Windows 10 / 11, Linux); at least one agent that is installed and signed in, such as Claude Code or Codex.</li><li><strong>Non-goals</strong>: <ul><li>No teaching of Claude Code or Codex themselves; go to <a href="./../claude/">Claude Code</a> and <a href="./../codex/">Codex</a>.</li><li>No running models locally. The official FAQ states that T3 Code does not support local models.</li><li>No setting up Tailscale; go to <a href="./../tailscale/">Tailscale</a>.</li><li>No expansion of T3 Chat, a separate product.</li></ul></li></ul><h2 id="product-family" tabindex="-1">Product family <a class="header-anchor" href="#product-family" aria-label="Permalink to &quot;Product family&quot;">​</a></h2><p>Official names are copied from official pages and repository docs. This directory has only three pages, so most family members land in a section of the tutorial.</p><table tabindex="0"><thead><tr><th>Official name</th><th>Official URL</th><th>On this site</th></tr></thead><tbody><tr><td><strong>Desktop app</strong> (macOS / Windows / Linux)</td><td><a href="https://t3.codes/download" target="_blank" rel="noreferrer">t3.codes/download</a></td><td>Own page: <a href="./t3code.html">tutorial</a>, sections 6 and 7</td></tr><tr><td><strong><code>t3</code> command</strong></td><td>Terminal block of the download page, <a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/install.md" target="_blank" rel="noreferrer">Install doc</a></td><td>Own page: <a href="./t3code.html">tutorial</a>, section 6</td></tr><tr><td><strong>Web</strong> (hosted web app)</td><td><a href="https://app.t3.codes" target="_blank" rel="noreferrer">app.t3.codes</a></td><td>Own page: <a href="./t3code.html">tutorial</a>, section 8, subsection 2</td></tr><tr><td><strong>Mobile app</strong> (iOS and Android)</td><td><a href="https://apps.apple.com/us/app/t3-code-remote-claude-more/id6787819824" target="_blank" rel="noreferrer">App Store</a>, <a href="https://play.google.com/store/apps/details?id=com.t3tools.t3code" target="_blank" rel="noreferrer">Google Play</a></td><td>Own page: <a href="./t3code.html">tutorial</a>, step 4 of section 6 and section 8, subsection 2</td></tr><tr><td><strong>Background service</strong></td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/background-service.md" target="_blank" rel="noreferrer">Running in the background</a></td><td>Own page: <a href="./t3code.html">tutorial</a>, section 8, subsection 7</td></tr><tr><td><strong>T3 Connect</strong> (including the relay)</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/remote-access.md" target="_blank" rel="noreferrer">Remote access</a>, <a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/internals/06_t3-connect.md" target="_blank" rel="noreferrer">T3 Connect design notes</a></td><td>Own pages: <a href="./t3code.html">tutorial</a> and <a href="./source.html">source code walkthrough</a></td></tr><tr><td><strong>Guest links</strong> (beta)</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/guest-links.md" target="_blank" rel="noreferrer">Guest links</a></td><td>Own page: <a href="./t3code.html">tutorial</a>, section 11</td></tr><tr><td><strong>Managed policy</strong></td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/managed-policy.md" target="_blank" rel="noreferrer">Managed policy</a></td><td>Own page: <a href="./t3code.html">tutorial</a>, section 11</td></tr><tr><td><strong>Outside agents</strong> (T3 Code&#39;s MCP server)</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/outside-agents.md" target="_blank" rel="noreferrer">Outside agents</a></td><td>One row in this map: lets Claude Code, Codex or ChatGPT in your terminal drive T3 Code threads the other way round</td></tr><tr><td><strong>ACP Registry agents</strong></td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/providers-acp.md" target="_blank" rel="noreferrer">ACP providers</a></td><td>One row in this map: for the concept see section 3 of the <a href="./t3code.html">tutorial</a>; for the steps to add one see the official page</td></tr><tr><td><strong>Workflows</strong> (early feature, in Labs)</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/workflows.md" target="_blank" rel="noreferrer">Workflows</a></td><td>One row in this map: chain agents, schedules and human approval into one resumable run with TypeScript</td></tr><tr><td><strong>Device panel</strong> (simulator panel)</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/devices.md" target="_blank" rel="noreferrer">Devices</a></td><td>One row in this map: view an iOS simulator or an Android emulator next to a thread</td></tr><tr><td><strong>Triage</strong></td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/triage.md" target="_blank" rel="noreferrer">Triage an issue</a></td><td>One row in this map: for what it is see section 3 of the <a href="./t3code.html">tutorial</a></td></tr><tr><td><strong>T3 Chat</strong> (another product)</td><td>See the <a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/faq.md" target="_blank" rel="noreferrer">FAQ</a></td><td>One row in this map: the one use this page verified is that linking an account raises the T3 Connect machine limit</td></tr></tbody></table><h3 id="names-that-collide" tabindex="-1">Names that collide <a class="header-anchor" href="#names-that-collide" aria-label="Permalink to &quot;Names that collide&quot;">​</a></h3><ul><li><strong>T3 Code ≠ T3 Chat.</strong> The latter is another T3 product. This page verified one use for it in the T3 Code docs: after you link a paid T3 Chat account, T3 Connect can link more machines.</li><li><strong>T3 Code ≠ Claude Code or Codex.</strong> It is the driver; those two are the agents being driven. The official FAQ says: &quot;T3 Code uses those harnesses. It is not a harness, and it does not work without one.&quot;</li><li><strong>T3 Tools, Inc. and <code>pingdotgg</code>.</strong> The former is the company name written on official pages; the latter is its GitHub organization name.</li><li><strong>T3 Connect ≠ Tailscale.</strong> The former is T3&#39;s own remote connection method; the latter is a third-party network, which T3 Code treats as another optional connection route.</li><li><strong>The <code>t3</code> command and the desktop app are not two products.</strong> They are two ways to start the same server, and the desktop app ships with <code>t3</code> as well.</li><li><strong>The name is not in the open-source license.</strong> MIT covers only the source code. The official team requires public forks to replace the T3 Code name and icon and to state that they are not affiliated with the official project.</li></ul><h2 id="what-problem-it-solves" tabindex="-1">What problem it solves <a class="header-anchor" href="#what-problem-it-solves" aria-label="Permalink to &quot;What problem it solves&quot;">​</a></h2><h3 id="without-it-and-with-it" tabindex="-1">Without it and with it <a class="header-anchor" href="#without-it-and-with-it" aria-label="Permalink to &quot;Without it and with it&quot;">​</a></h3><p>The left column is the situation many readers are in. This page treats it as a premise and makes no claims about the details of any particular product.</p><table tabindex="0"><thead><tr><th>Task</th><th>A separate terminal or app for each</th><th>With T3 Code</th></tr></thead><tbody><tr><td>Using two agents at once</td><td>Two windows, each with its own interface</td><td>Switch inside one interface. README: Every agent in one place</td></tr><tr><td>Wanting to switch models midway through a task</td><td>You carry the context over yourself</td><td>Switch provider inside the same thread; T3 Code carries the conversation context over within a budget</td></tr><tr><td>Running several tasks in parallel</td><td>Open your own terminals and manage your own branches</td><td>One worktree per thread, each with its own branch and working directory</td></tr><tr><td>Seeing what changed and committing</td><td>Each has its own way</td><td>A unified diff panel and Git operations</td></tr><tr><td>You are away from the computer</td><td>You can approve only when you are back at it</td><td>Approve from the phone and receive notifications</td></tr><tr><td>The agent process crashes</td><td>Depends on each tool&#39;s own recovery ability</td><td>The thread record is stored persistently; the official glossary states that it survives provider process exits</td></tr></tbody></table><h3 id="versus-the-alternatives" tabindex="-1">Versus the alternatives <a class="header-anchor" href="#versus-the-alternatives" aria-label="Permalink to &quot;Versus the alternatives&quot;">​</a></h3><p>Only what can be verified is written. For other vendors&#39; products, links go to this site&#39;s own pages for each.</p><table tabindex="0"><thead><tr><th>Option</th><th>What it is</th><th>Evidence</th></tr></thead><tbody><tr><td>Each agent&#39;s own interface</td><td>Claude Code and Codex each have their own terminal and desktop app</td><td>This site: <a href="./../claude/">Claude Code</a>, <a href="./../codex/">Codex</a></td></tr><tr><td><strong>T3 Code</strong></td><td>A cross-vendor driver; bring your own subscriptions, and it drives the agents already installed</td><td>README, FAQ</td></tr><tr><td>Codex desktop app, Conductor, Claude Desktop, Cursor Glass</td><td>The four products T3 Code officially names as having &quot;inspired it&quot;; the official docs say none of them met T3 Code&#39;s own bar</td><td>FAQ: Why use T3 Code instead of Claude Code or the Codex app?</td></tr><tr><td><a href="./../cindy/">Cindy</a></td><td>A multi-agent workspace product of the same kind</td><td>See the Cindy page for the comparison; this page has not verified its details</td></tr><tr><td><a href="./../tailscale/">Tailscale</a></td><td>A connection route that solves &quot;how to connect back to your computer&quot;; it does not drive agents</td><td>T3 Code&#39;s Remote access doc lists it as an option besides T3 Connect</td></tr></tbody></table><h2 id="quick-decision-which-one-should-i-use" tabindex="-1">Quick decision: which one should I use <a class="header-anchor" href="#quick-decision-which-one-should-i-use" aria-label="Permalink to &quot;Quick decision: which one should I use&quot;">​</a></h2><table tabindex="0"><thead><tr><th>My situation</th><th>What to use</th></tr></thead><tbody><tr><td>One agent only, used occasionally</td><td>Start with its own interface: <a href="./../claude/">Claude Code</a> or <a href="./../codex/">Codex</a></td></tr><tr><td>Two or more agents at once, and you want to switch between them in one window</td><td>The T3 Code desktop app</td></tr><tr><td>Run several tasks in parallel, each on its own branch</td><td>T3 Code; choose <strong>New worktree</strong> when you start a thread</td></tr><tr><td>Often away from the computer, and you want to approve from the phone</td><td>T3 Code plus T3 Connect, plus the mobile app</td></tr><tr><td>The company network blocks T3 Connect&#39;s outbound ports</td><td>T3 Code plus a direct LAN connection, or <a href="./../tailscale/">Tailscale</a></td></tr><tr><td>Run it on your own server and connect remotely most of the time</td><td>Install it as a background service with <code>t3 up</code>, then connect with <a href="https://app.t3.codes" target="_blank" rel="noreferrer">app.t3.codes</a> or the phone</td></tr><tr><td>Do not want to pass through any T3 service</td><td>Leave T3 Connect off, use only a direct LAN or Tailscale connection, and turn telemetry off</td></tr><tr><td>Set a permission ceiling for the team&#39;s machines</td><td>T3 Code&#39;s managed policy</td></tr><tr><td>Compare it with similar products</td><td><a href="./../cindy/">Cindy</a></td></tr></tbody></table><h2 id="how-to-read-this-directory" tabindex="-1">How to read this directory <a class="header-anchor" href="#how-to-read-this-directory" aria-label="Permalink to &quot;How to read this directory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What you can do after reading</th><th>When to read</th></tr></thead><tbody><tr><td><a href="./t3code.html">Tutorial</a></td><td>Install it, run the first thread end to end, choose a permission mode by scenario, continue from the phone, and state three security boundaries</td><td>The first time you use it</td></tr><tr><td><a href="./source.html">Source code walkthrough</a></td><td>Follow the data flow of one thread, see which code enforces the permission modes, and understand the trust model of T3 Connect</td><td>After you are comfortable with it, or when preparing to submit a PR to T3 Code</td></tr></tbody></table><p>Suggested order:</p><ol><li><strong>Read the <a href="./t3code.html">tutorial</a> first.</strong> The 10-minute vertical slice is in section 7 and runs as soon as the install is done. When a concept is unclear, go back to section 3.</li><li><strong>Then read the <a href="./source.html">source code walkthrough</a>.</strong> It assumes you can already start a thread and switch permission modes; otherwise the words &quot;command&quot;, &quot;event&quot; and &quot;effect&quot; have nothing to attach to.</li><li><strong>Come back to the family table on this page.</strong> The tutorial expands only the most used members of the family; look up guest links, managed policy, the MCP server and the rest as you need them.</li></ol><h2 id="official-resources-further-reading" tabindex="-1">Official resources (further reading) <a class="header-anchor" href="#official-resources-further-reading" aria-label="Permalink to &quot;Official resources (further reading)&quot;">​</a></h2><p>The documentation links in the repository are pinned to commit <code>d00aaac8</code>; to read the latest version, replace the commit hash with <code>main</code>.</p><ul><li><a href="https://t3.codes" target="_blank" rel="noreferrer">Official site t3.codes</a>: positioning, the download entry, and a one-sentence list of the agents it supports.</li><li><a href="https://t3.codes/download" target="_blank" rel="noreferrer">Download page</a>: installers for the three desktop platforms, the command-line install method, and the mobile store entries.</li><li><a href="https://app.t3.codes" target="_blank" rel="noreferrer">app.t3.codes</a>: the hosted web app, which only connects to your own environment.</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/README.md" target="_blank" rel="noreferrer">Repository README</a>: what it is, which agents it supports, how to install it, and the license and brand policy.</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/README.md" target="_blank" rel="noreferrer">docs/README.md</a>: the table of contents for all the documentation, split into three parts: usage, internal design and the operations handbook.</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/install.md" target="_blank" rel="noreferrer">Install T3 Code</a>: installation on each platform and how to sign in to each provider.</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/faq.md" target="_blank" rel="noreferrer">FAQ</a>: cost, quotas, remote access, account bans, and &quot;is T3 Code a harness&quot;.</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/internals/01_architecture.md" target="_blank" rel="noreferrer">Architecture</a>: ownership boundaries and the design constraint &quot;write to the database first, run effects afterwards&quot;.</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>: who is trusted, what counts as a vulnerability, and what is intentional.</li><li><a href="https://github.com/pingdotgg/t3code/releases" target="_blank" rel="noreferrer">GitHub Releases</a>: change logs for stable releases and nightlies.</li><li><a href="https://github.com/pingdotgg/t3code/discussions/categories/ideas" target="_blank" rel="noreferrer">Ideas under Discussions</a>: where to propose features. The README states that a feature must first have an accepted discussion.</li><li><a href="https://discord.gg/jn4EGJjrvv" target="_blank" rel="noreferrer">Discord</a>: the help channel given in the README; the invite page shows the server as Theo&#39;s Typesafe Cult.</li><li><a href="https://t3.gg/blog/post/what-is-a-harness" target="_blank" rel="noreferrer">What is a &quot;harness&quot;?</a>: the official blog post on how the work is divided between the model, the harness, the agent and T3 Code.</li><li><a href="https://agentclientprotocol.com/overview/introduction" target="_blank" rel="noreferrer">Agent Client Protocol</a>: the official introduction to ACP.</li></ul><h2 id="related-pages-on-this-site" tabindex="-1">Related pages (on this site) <a class="header-anchor" href="#related-pages-on-this-site" aria-label="Permalink to &quot;Related pages (on this site)&quot;">​</a></h2><ul><li><a href="./t3code.html">Tutorial</a>, <a href="./source.html">Source code walkthrough</a>: the other two pages in this directory.</li><li><a href="./../claude/">Claude Code</a>, <a href="./../codex/">Codex</a>: the two agents that T3 Code drives.</li><li><a href="./../codex/dot.html">Codex Dot</a>: the always-on agent on OpenAI&#39;s side; read it alongside this page when comparing &quot;who keeps pushing a task forward&quot;.</li><li><a href="./../cindy/">Cindy</a>: a multi-agent workspace product of the same kind.</li><li><a href="./../tailscale/">Tailscale</a>: a connection route other than T3 Connect.</li><li><a href="./../uu-remote/">UU Remote</a>: another kind of approach to &quot;the person is not at the computer&quot;; work out which kind you need first.</li></ul>',30)])])}const b=e(d,[["render",n]]);export{m as __pageData,b as default};
